void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = fragCoord / iResolution.xy;
  int touche = int(uv.x * 255.0);
  float etat = texelFetch(iChannel0, ivec2(touche, 0), 0).x;
  float appui = texelFetch(iChannel0, ivec2(touche, 1), 0).x;
  float bascule = texelFetch(iChannel0, ivec2(touche, 2), 0).x;
  fragColor = vec4(vec3(etat, appui, bascule) + 0.15 * uv.y, 1.0);
}
